package pebble

import (
	"bytes"
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"slices"
	"time"

	"github.com/cockroachdb/pebble/v2"
	logging "github.com/ipfs/go-log/v2"
	"github.com/ipni/go-indexer-core"
	"github.com/ipni/go-indexer-core/metrics"
	"github.com/libp2p/go-libp2p/core/peer"
	"github.com/multiformats/go-multihash"
)

const (
	// defaultKeyerLength is the length of hashes generated by the default keyer, blake3Keyer.
	defaultKeyerLength = 20

	// metricsReportingInterval is the interval at which metrics are reported
	metricsReportingInterval = 30 * time.Second
)

var (
	log = logging.Logger("store/pebble")

	_ indexer.Interface = (*store)(nil)
)

type store struct {
	db *pebble.DB
	// Only support binary format since in pebble we need the capability to merge keys and
	// there is little reason for store values in any format other than binary for performance
	// characteristics.
	// Note, pebble is using a zero-copy variation of marshaller to allow optimizations in
	// cases where the value need not to be copied. The root level binary codec copies on
	// unmarshal every time.
	vcodec        *codec
	p             *pool
	closed        bool
	comparer      *pebble.Comparer
	cancelMetrics context.CancelFunc
}

// New instantiates a new instance of a store backed by Pebble.
// Note that any Merger value specified in the given options will be overridden.
func New(path string, opts *pebble.Options) (indexer.Interface, error) {
	p := newPool()
	c := &codec{
		p: p,
	}
	if opts == nil {
		opts = &pebble.Options{}
	}
	opts.EnsureDefaults()
	// Override Merger since the store relies on a specific implementation of it
	// to handle read-free writing of value-keys; see: valueKeysValueMerger.
	opts.Merger = newValueKeysMerger(c)
	db, err := pebble.Open(path, opts)
	if err != nil {
		return nil, err
	}

	metricsContext, cancelFunc := context.WithCancel(context.Background())

	st := &store{
		db:            db,
		p:             p,
		vcodec:        c,
		comparer:      opts.Comparer,
		cancelMetrics: cancelFunc,
	}

	go metrics.ObservePebbleMetrics(metricsContext, metricsReportingInterval, db)

	return st, nil
}

func (s *store) Get(mh multihash.Multihash) ([]indexer.Value, bool, error) {
	keygen := s.p.leaseBlake3Keyer()
	mhk, err := keygen.multihashKey(mh)
	_ = keygen.Close()
	if err != nil {
		return nil, false, err
	}
	vkb, vkbClose, err := s.db.Get(mhk.buf)
	_ = mhk.Close()
	if err == pebble.ErrNotFound {
		return nil, false, nil
	}
	if err != nil {
		log.Errorw("can't find multihash", "err", err)
		return nil, false, err
	}

	vks, err := s.vcodec.unmarshalValueKeys(vkb)
	_ = vkbClose.Close()
	if err != nil {
		return nil, false, err
	}
	defer vks.Close()

	// Optimistically set the capacity of values slice to the number of value-keys
	// in order to reduce the append footprint in the loop below.
	values := make([]indexer.Value, 0, len(vks.keys))
	for _, vk := range vks.keys {
		vs, vCloser, err := s.db.Get(vk.buf)
		if err == pebble.ErrNotFound {
			// TODO find an efficient way to opportunistically clean up
			continue
		}
		if err != nil {
			log.Errorw("can't find value", "err", err)
			return nil, false, err
		}

		v, err := s.vcodec.unmarshalValue(vs)
		_ = vCloser.Close()
		if err != nil {
			return nil, false, err
		}
		values = append(values, *v)
	}
	return values, len(values) != 0, nil
}

// Put implemeents indexer.Interface. This implementation reorders the given multihashes.
func (s *store) Put(v indexer.Value, mhs ...multihash.Multihash) error {
	if len(v.MetadataBytes) == 0 {
		return errors.New("value missing metadata")
	}

	// Sort multihashes before insertion to reduce cursor churn. Since a
	// multihash key is a prefix plus the multihash itself, sorting the
	// multihashes means their resulting keys will also be sorted.
	if len(mhs) > 1 {
		// Make a copy to reorder.
		slices.SortFunc(mhs, func(a, b multihash.Multihash) int { return bytes.Compare(a, b) })
	}

	keygen := s.p.leaseBlake3Keyer()
	defer keygen.Close()

	b := s.db.NewBatch()
	defer b.Close()

	vk, err := s.findOrCreateContextValueKey(b, keygen, v.ProviderID, v.ContextID)
	if err != nil {
		return err
	}
	defer vk.Close()

	for _, mh := range mhs {
		mhk, err := keygen.multihashKey(mh)
		if err != nil {
			return err
		}
		err = b.Merge(mhk.buf, vk.buf, pebble.NoSync)
		_ = mhk.Close()
		if err != nil {
			return err
		}
	}

	vs, c, err := s.vcodec.marshalValue(&v)
	if err != nil {
		return err
	}
	defer c.Close()

	// Don't bother checking if the value has changed, and write it anyway. Because, otherwise
	// we need to use an IndexedBatch which is generally slower than Batch, and the majority
	// of writing here is the writing of multihashes.
	//
	// TODO: experiment to see if it is indeed faster to always write the value instead of
	//       check if it's changed before writing.
	if err = b.Set(vk.buf, vs, pebble.NoSync); err != nil {
		return err
	}

	return b.Commit(pebble.NoSync)
}

// Remove implemeents indexer.Interface. This implementation reorders the given multihashes.
func (s *store) Remove(v indexer.Value, mhs ...multihash.Multihash) error {
	// Sort multihashes before insertion to reduce cursor churn. Since a
	// multihash key is a prefix plus the multihash itself, sorting the
	// multihashes means their resulting keys will also be sorted.
	if len(mhs) > 1 {
		slices.SortFunc(mhs, func(a, b multihash.Multihash) int { return bytes.Compare(a, b) })
	}

	keygen := s.p.leaseBlake3Keyer()
	defer keygen.Close()

	vk, err := s.findContextValueKey(keygen, v.ProviderID, v.ContextID)
	if err != nil {
		return err
	}
	defer vk.Close()

	b := s.db.NewBatch()
	defer b.Close()

	dvk := s.p.leaseKey()
	dvk.maybeGrow(1 + len(vk.buf))
	dvk.append(byte(mergeDeleteKeyPrefix))
	dvk.append(vk.buf...)
	defer dvk.Close()

	for _, mh := range mhs {
		mhk, err := keygen.multihashKey(mh)
		if err != nil {
			return err
		}
		err = b.Merge(mhk.buf, dvk.buf, pebble.NoSync)
		_ = mhk.Close()
		if err != nil {
			return err
		}
	}

	// TODO: opportunistically delete garbage key value keys by checking a list
	// of removed providers during merge.
	return b.Commit(pebble.NoSync)
}

func (s *store) RemoveProvider(_ context.Context, pid peer.ID) error {
	keygen := s.p.leaseBlake3Keyer()
	defer keygen.Close()

	vStart, vEnd, err := keygen.valuesByProviderKeyRange(pid)
	if err != nil {
		return err
	}
	defer func() {
		_ = vStart.Close()
		_ = vEnd.Close()
	}()

	mStart, mEnd, err := keygen.contextMapsByProviderKeyRange(pid)
	if err != nil {
		return err
	}
	defer func() {
		_ = mStart.Close()
		_ = mEnd.Close()
	}()

	b := s.db.NewBatch()
	defer b.Close()
	if err = b.DeleteRange(vStart.buf, vEnd.buf, pebble.NoSync); err != nil {
		return err
	}
	if err = b.DeleteRange(mStart.buf, mEnd.buf, pebble.NoSync); err != nil {
		return err
	}
	return b.Commit(pebble.NoSync)
}

func (s *store) RemoveProviderContext(pid peer.ID, ctxID []byte) error {
	keygen := s.p.leaseBlake3Keyer()
	defer keygen.Close()

	vk, mapKey, _, err := s.lookupContext(keygen, pid, ctxID)
	if err != nil {
		return err
	}
	defer vk.Close()
	defer mapKey.Close()

	b := s.db.NewBatch()
	defer b.Close()
	if err = b.Delete(vk.buf, pebble.NoSync); err != nil {
		return err
	}
	if err = b.Delete(mapKey.buf, pebble.NoSync); err != nil {
		return err
	}
	return b.Commit(pebble.NoSync)
}

// findContextValueKey returns the value key for a provider and context.
// If mapping does not exist, a legacy value key is returned.
func (s *store) findContextValueKey(keygen *blake3Keyer, pid peer.ID, ctxID []byte) (*key, error) {
	vk, mapKey, _, err := s.lookupContext(keygen, pid, ctxID)
	if err != nil {
		return nil, err
	}
	defer mapKey.Close()

	return vk, nil
}

// findOrCreateContextValueKey returns the value key for a provider and context.
// An existing context-map entry or a live legacy value key is reused. Otherwise
// a new token is stored in b and used as the context half of the returned key.
func (s *store) findOrCreateContextValueKey(
	b *pebble.Batch,
	keygen *blake3Keyer,
	pid peer.ID,
	ctxID []byte,
) (
	*key,
	error,
) {
	vk, mapKey, mapped, err := s.lookupContext(keygen, pid, ctxID)
	if err != nil {
		return nil, err
	}
	defer mapKey.Close()

	if mapped {
		return vk, nil
	}

	switch _, closer, err := s.db.Get(vk.buf); {
	case err == pebble.ErrNotFound:
		// No context value data yet, create new mapping
		_ = vk.Close()
		return s.createNewContextMapping(b, mapKey, keygen, pid)

	case err != nil:
		// Some internal error
		_ = vk.Close()
		return nil, err

	default: // err == nil
		_ = closer.Close()
		// Context value at the legacy key already exists, return it
		return vk, nil
	}
}

// createNewContextMapping generates a random token, adds the context-map entry
// for it to b, and returns the value key built from the token.
func (s *store) createNewContextMapping(b *pebble.Batch, mapKey *key, keygen *blake3Keyer, pid peer.ID) (*key, error) {
	token := make([]byte, contextTokenLength)
	if _, err := rand.Read(token); err != nil {
		return nil, err
	}
	vk, err := keygen.valueKeyWithToken(pid, token, false)
	if err != nil {
		return nil, err
	}
	if err := b.Set(mapKey.buf, token, pebble.NoSync); err != nil {
		_ = vk.Close()
		return nil, err
	}
	return vk, nil
}

// lookupContext returns the value key and context-map key for a provider and context.
// mapped is true when vk was built from a stored token. On success both keys are non-nil
// and the caller must close the keys.
func (s *store) lookupContext(
	keygen *blake3Keyer,
	pid peer.ID,
	ctxID []byte,
) (
	vk *key,
	mapKey *key,
	mapped bool,
	err error,
) {
	mapKey, err = keygen.contextMapKey(pid, ctxID)
	if err != nil {
		return nil, nil, false, err
	}

	switch tokenBytes, closer, err := s.db.Get(mapKey.buf); {
	case err == pebble.ErrNotFound:
		// No mapping found, fall back to the legacy value key, which holds
		// the same provider and context hashes as the map key.
		return mapKey.replacePrefix(valueKeyPrefix), mapKey, false, nil

	case err != nil:
		// Some internal error
		_ = mapKey.Close()
		return nil, nil, false, err

	default: // err == nil
		// Found existing mapping
		defer closer.Close()

		if len(tokenBytes) != contextTokenLength {
			_ = mapKey.Close()
			return nil, nil, false, fmt.Errorf("invalid context token length: %d", len(tokenBytes))
		}

		vk, err = keygen.valueKeyWithToken(pid, tokenBytes, false)
		if err != nil {
			_ = mapKey.Close()
			return nil, nil, false, err
		}

		return vk, mapKey, true, nil
	}
}

func (s *store) Size() (int64, error) {
	sizeEstimate, err := s.db.EstimateDiskUsage([]byte{0}, []byte{0xff})
	return int64(sizeEstimate), err
}

func (s *store) Flush() error {
	return s.db.Flush()
}

func (s *store) Close() error {
	if s.closed {
		return nil
	}
	s.closed = true
	// Stop reporting pebble metrics.
	s.cancelMetrics()

	// Close also performs a flush.
	return s.db.Close()
}

// Stats gathers statistics about the values indexed by Pebble store.
// The statistic gathering can be expensive and may be slow to calculate.
// The numbers returned are estimated, must not be interpreted as exact and will not include
// records that are not flushed.
func (s *store) Stats() (*indexer.Stats, error) {
	sst, err := s.db.SSTables(pebble.WithProperties())
	if err != nil {
		return nil, err
	}
	keygen := s.p.leaseBlake3Keyer()
	defer keygen.Close()

	start, end, err := keygen.multihashesKeyRange()
	if err != nil {
		return nil, err
	}
	defer func() {
		_ = start.Close()
		_ = end.Close()
	}()
	var stats indexer.Stats
	for _, is := range sst {
		for _, info := range is {
			// SST file entries may overlap beyont start or end key. Include all such overlapping
			// SST files in the count; this effectively implies an over estimation of unique
			// multihashes. This is fine since the number of multihashes is expected to be
			// overwhelmingly larger than provider records.
			if s.comparer.Compare(start.buf, info.Smallest.UserKey) <= 0 ||
				s.comparer.Compare(end.buf, info.Largest.UserKey) <= 0 {
				stats.MultihashCount += info.Properties.NumEntries
			}
		}
	}
	return &stats, nil
}
